    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen', 'Ubuntu', 'Cantarell', sans-serif;
    color: #e0e0e0;
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 20px;
}

.container {
    width: 100%;
    max-width: 500px;
}

.form-wrapper {
    background: #0f1621;
    border-radius: 12px;
    padding: 40px;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
    border: 1px solid rgba(255, 255, 255, 0.1);
}

h1 {
    font-size: 28px;
    font-weight: 600;
    margin-bottom: 8px;
    color: #ffffff;
}

.form-subtitle {
    font-size: 14px;
    color: #a0a0a0;
    margin-bottom: 32px;
}

form {
    display: flex;
    flex-direction: column;
    gap: 24px;
}

.form-field {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

label {
    font-size: 14px;
    font-weight: 500;
    color: #e0e0e0;
    display: flex;
    align-items: center;
    gap: 6px;
}

.optional {
    font-size: 12px;
    color: #808080;
    font-weight: 400;
}

input[type="text"],
input[type="email"],
input[type="tel"] {
    padding: 12px 14px;
    border: 2px solid rgba(255, 255, 255, 0.15);
    background: rgba(255, 255, 255, 0.05);
    border-radius: 8px;
    font-size: 14px;
    color: #ffffff;
    transition: all 0.3s ease;
    font-family: inherit;
}

input[type="text"]::placeholder,
input[type="email"]::placeholder,
input[type="tel"]::placeholder {
    color: #606060;
}

input[type="text"]:focus,
input[type="email"]:focus,
input[type="tel"]:focus {
    outline: none;
    border-color: #4a9eff;
    background: rgba(255, 255, 255, 0.08);
    box-shadow: 0 0 0 3px rgba(74, 158, 255, 0.1);
}

input.error {
    border-color: #ff4757;
    background: rgba(255, 71, 87, 0.05);
}

input.error:focus {
    border-color: #ff4757;
    box-shadow: 0 0 0 3px rgba(255, 71, 87, 0.1);
}

input.success {
    border-color: #2ed573;
}

input.success:focus {
    border-color: #2ed573;
    box-shadow: 0 0 0 3px rgba(46, 213, 115, 0.1);
}

.helper-text {
    font-size: 12px;
    color: #808080;
    margin-top: 4px;
}

.validation-message {
    font-size: 13px;
    color: #ff4757;
    min-height: 18px;
    display: none;
}

.validation-message.show {
    display: block;
}

.submit-button {
    padding: 12px 24px;
    background: linear-gradient(135deg, #4a9eff 0%, #357abd 100%);
    color: #ffffff;
    border: none;
    border-radius: 8px;
    font-size: 15px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s ease;
    margin-top: 8px;
    font-family: inherit;
}

.submit-button:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 20px rgba(74, 158, 255, 0.3);
}

.submit-button:active {
    transform: translateY(0);
}

.submit-button:disabled {
    opacity: 0.6;
    cursor: not-allowed;
    transform: none;
}

.success-message {
    margin-top: 24px;
    padding: 16px;
    background: rgba(46, 213, 115, 0.1);
    border: 2px solid #2ed573;
    border-radius: 8px;
    color: #2ed573;
    font-size: 14px;
    display: none;
    text-align: center;
    font-weight: 500;
}

.success-message.show {
    display: block;
}

@media (max-width: 600px) {
    .form-wrapper {
        padding: 24px;
    }

    h1 {
        font-size: 24px;
    }

    .form-field {
        gap: 6px;
    }
}
