    constructor(formId) {
        this.form = document.getElementById(formId);
        this.fields = {
            fullName: {
                element: document.getElementById('fullName'),
                errorElement: document.getElementById('fullNameError'),
                required: true,
                validate: (value) => this.validateRequired(value)
            },
            email: {
                element: document.getElementById('email'),
                errorElement: document.getElementById('emailError'),
                required: true,
                validate: (value) => this.validateEmail(value)
            },
            phone: {
                element: document.getElementById('phone'),
                errorElement: document.getElementById('phoneError'),
                required: false,
                validate: (value) => this.validatePhone(value)
            }
        };
        this.successMessage = document.getElementById('successMessage');
        this.init();
    }

    init() {
        this.form.addEventListener('submit', (e) => this.handleSubmit(e));

        Object.values(this.fields).forEach(field => {
            field.element.addEventListener('blur', () => this.validateField(field));
            field.element.addEventListener('input', () => this.clearError(field));
        });
    }

    validateRequired(value) {
        return value.trim().length > 0;
    }

    validateEmail(value) {
        if (value.trim().length === 0) {
            return false;
        }
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return emailRegex.test(value);
    }

    validatePhone(value) {
        if (value.trim().length === 0) {
            return true;
        }
        const phoneRegex = /^[\d\s\-()]+$/;
        if (!phoneRegex.test(value)) {
            return false;
        }
        const digitsOnly = value.replace(/\D/g, '');
        return digitsOnly.length === 10;
    }

    validateField(field) {
        const value = field.element.value;

        if (field.required && !field.validate(value)) {
            this.showError(field);
            return false;
        } else if (!field.required && value.trim().length > 0 && !field.validate(value)) {
            this.showError(field);
            return false;
        } else {
            this.clearError(field);
            return true;
        }
    }

    showError(field) {
        const value = field.element.value;
        let errorMessage = '';

        if (field === this.fields.fullName) {
            errorMessage = value.trim() === '' ? 'Full name is required' : 'Invalid full name';
        } else if (field === this.fields.email) {
            if (value.trim() === '') {
                errorMessage = 'Email address is required';
            } else {
                errorMessage = 'Please enter a valid email address';
            }
        } else if (field === this.fields.phone) {
            if (value.trim() !== '') {
                const digitsOnly = value.replace(/\D/g, '');
                if (digitsOnly.length !== 10) {
                    errorMessage = 'Phone number must contain exactly 10 digits';
                } else {
                    errorMessage = 'Please enter a valid phone number format';
                }
            }
        }

        field.errorElement.textContent = errorMessage;
        field.errorElement.classList.add('show');
        field.element.classList.add('error');
        field.element.classList.remove('success');
    }

    clearError(field) {
        field.errorElement.textContent = '';
        field.errorElement.classList.remove('show');
        field.element.classList.remove('error');
    }

    handleSubmit(e) {
